//! Differential ratchet for
//! `src/engine/battleScriptTrycopyabilityOpcode.ts`. Expected complete
//! projected outputs, typed controls, and exact ordered role errors are
//! generated by executing the canonical TypeScript opcode handler; regenerate
//! with `node --experimental-strip-types
//! core-rs/tools/gen-battle-script-trycopyability-vectors.mjs`.

use std::collections::BTreeSet;

use factory_core::battle_script_trycopyability::{
    apply_battle_script_trycopyability, BattleScriptTrycopyabilityBattlerState,
    BattleScriptTrycopyabilityControl, BattleScriptTrycopyabilityOutcome,
    BattleScriptTrycopyabilityRoles, BattleScriptTrycopyabilityRules,
    BATTLE_SCRIPT_TRYCOPYABILITY_ABILITY_NONE, BATTLE_SCRIPT_TRYCOPYABILITY_ABILITY_WONDER_GUARD,
    BATTLE_SCRIPT_TRYCOPYABILITY_BATTLERS, BATTLE_SCRIPT_TRYCOPYABILITY_BATTLER_COUNT,
};
use factory_core::battle_script_trycopyability_vectors_gen::{
    BattleScriptTrycopyabilityVectorCase, BattleScriptTrycopyabilityVectorState,
    BATTLE_SCRIPT_TRYCOPYABILITY_ATTACKER_DOMAIN, BATTLE_SCRIPT_TRYCOPYABILITY_BRANCH_CENSUS,
    BATTLE_SCRIPT_TRYCOPYABILITY_CASES, BATTLE_SCRIPT_TRYCOPYABILITY_CATEGORY_CENSUS,
    BATTLE_SCRIPT_TRYCOPYABILITY_DOMAIN_CENSUS,
    BATTLE_SCRIPT_TRYCOPYABILITY_FAILURE_ABILITY_DOMAIN,
    BATTLE_SCRIPT_TRYCOPYABILITY_FULL_DOMAIN_ROLE_PAIR,
    BATTLE_SCRIPT_TRYCOPYABILITY_LAST_USED_ABILITY_BOUNDARY_DOMAIN,
    BATTLE_SCRIPT_TRYCOPYABILITY_SUCCESS_ABILITY_BOUNDARY_DOMAIN,
    BATTLE_SCRIPT_TRYCOPYABILITY_TARGET_ABILITY_DOMAIN, BATTLE_SCRIPT_TRYCOPYABILITY_TARGET_DOMAIN,
    BATTLE_SCRIPT_TRYCOPYABILITY_VECTOR_CORPUS_SHA256,
};

fn rules(value: BattleScriptTrycopyabilityVectorState) -> BattleScriptTrycopyabilityRules {
    BattleScriptTrycopyabilityRules {
        battlers: value
            .abilities
            .map(|ability| BattleScriptTrycopyabilityBattlerState { ability }),
        last_used_ability: value.last_used_ability,
        selector_roles: BattleScriptTrycopyabilityRoles {
            attacker: value.attacker,
            target: value.target,
        },
    }
}

fn vector_state(value: BattleScriptTrycopyabilityRules) -> BattleScriptTrycopyabilityVectorState {
    BattleScriptTrycopyabilityVectorState {
        abilities: value.battlers.map(|battler| battler.ability),
        last_used_ability: value.last_used_ability,
        attacker: value.selector_roles.attacker,
        target: value.selector_roles.target,
    }
}

#[test]
fn complete_projected_outputs_controls_exact_ordered_errors_and_input_preservation_match_canonical_typescript(
) {
    assert_eq!(BATTLE_SCRIPT_TRYCOPYABILITY_CASES.len(), 359);
    for (case_index, case) in BATTLE_SCRIPT_TRYCOPYABILITY_CASES.iter().enumerate() {
        execute_case(case_index, case);
    }
}

fn execute_case(case_index: usize, case: &BattleScriptTrycopyabilityVectorCase) {
    let input = rules(case.initial);
    let before = input;
    let mut current = input;
    let mut actual_controls = Vec::new();
    let mut actual_error = None;

    for application in 0..case.applications {
        let prior = current;
        match apply_battle_script_trycopyability(&current) {
            Ok(outcome) => {
                actual_controls.push(outcome.control);
                assert_transition_shape(case_index, case, application, prior, outcome);
                current = outcome.rules;
            }
            Err(error) => {
                actual_error = Some(error.to_string());
                break;
            }
        }
    }

    assert_eq!(
        input, before,
        "case {case_index} {}: native transformation mutated input",
        case.label,
    );
    match (actual_error, case.expected, case.expected_error) {
        (None, Some(expected), None) => {
            assert_eq!(
                actual_controls.as_slice(),
                case.controls,
                "case {case_index} {}: canonical control sequence",
                case.label,
            );
            assert_eq!(
                actual_controls.len(),
                usize::from(case.applications),
                "case {case_index} {}: successful sequence stopped early",
                case.label,
            );
            assert_eq!(
                vector_state(current),
                expected,
                "case {case_index} {}: complete projected output",
                case.label,
            );
        }
        (Some(error), None, Some(expected_error)) => {
            assert_eq!(
                actual_controls.as_slice(),
                case.controls,
                "case {case_index} {}: error must not produce a control result",
                case.label,
            );
            assert_eq!(
                error, expected_error,
                "case {case_index} {}: exact canonical role error",
                case.label,
            );
        }
        (error, expected, expected_error) => panic!(
            "case {case_index} {}: generated outcome shape disagrees with native result: error={error:?}, expected={expected:?}, expected_error={expected_error:?}",
            case.label,
        ),
    }
}

fn assert_transition_shape(
    case_index: usize,
    case: &BattleScriptTrycopyabilityVectorCase,
    application: u8,
    prior: BattleScriptTrycopyabilityRules,
    outcome: BattleScriptTrycopyabilityOutcome,
) {
    let attacker = prior.selector_roles.attacker.unwrap_or_else(|| {
        panic!(
            "case {case_index} {} application {application}: successful result had no attacker",
            case.label,
        )
    });
    let target = prior.selector_roles.target.unwrap_or_else(|| {
        panic!(
            "case {case_index} {} application {application}: successful result had no target",
            case.label,
        )
    });
    let target_ability = prior.battlers[target.index()].ability;
    assert_eq!(
        outcome.rules.selector_roles, prior.selector_roles,
        "case {case_index} {} application {application}: changed selector roles",
        case.label,
    );

    match outcome.control {
        // This unit-like enum variant deliberately cannot contain the canonical
        // machine's resolved absolute program counter.
        BattleScriptTrycopyabilityControl::FailJump => {
            assert!(
                BATTLE_SCRIPT_TRYCOPYABILITY_FAILURE_ABILITY_DOMAIN.contains(&target_ability),
                "case {case_index} {} application {application}: fail jump accepted target ability {target_ability}",
                case.label,
            );
            assert_eq!(
                outcome.rules, prior,
                "case {case_index} {} application {application}: fail jump changed complete narrow state",
                case.label,
            );
        }
        BattleScriptTrycopyabilityControl::Advance => {
            assert!(
                !BATTLE_SCRIPT_TRYCOPYABILITY_FAILURE_ABILITY_DOMAIN.contains(&target_ability),
                "case {case_index} {} application {application}: advance accepted rejected target ability {target_ability}",
                case.label,
            );
            for battler in BATTLE_SCRIPT_TRYCOPYABILITY_BATTLERS {
                if battler != attacker {
                    assert_eq!(
                        outcome.rules.battlers[battler.index()],
                        prior.battlers[battler.index()],
                        "case {case_index} {} application {application}: changed sibling battler {}",
                        case.label,
                        battler.as_u8(),
                    );
                }
            }
            assert_eq!(
                outcome.rules.battlers[attacker.index()].ability,
                target_ability,
                "case {case_index} {} application {application}: did not copy active target ability",
                case.label,
            );
            assert_eq!(
                outcome.rules.last_used_ability, target_ability,
                "case {case_index} {} application {application}: did not overwrite lastUsedAbility",
                case.label,
            );
        }
    }
}

#[test]
fn one_non_alias_pair_exhaustively_covers_target_u8_and_prior_last_used_boundaries() {
    let full_domain = BATTLE_SCRIPT_TRYCOPYABILITY_CASES
        .iter()
        .filter(|case| case.category == "non-alias-target-ability-u8-full-domain")
        .collect::<Vec<_>>();
    assert_eq!(full_domain.len(), 256);

    let (attacker, target) = BATTLE_SCRIPT_TRYCOPYABILITY_FULL_DOMAIN_ROLE_PAIR;
    let abilities = full_domain
        .iter()
        .map(|case| {
            assert_eq!(
                case.initial.attacker.map(|value| value.as_u8()),
                Some(attacker)
            );
            assert_eq!(case.initial.target.map(|value| value.as_u8()), Some(target));
            case.initial.abilities[usize::from(target)]
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(
        abilities,
        BATTLE_SCRIPT_TRYCOPYABILITY_TARGET_ABILITY_DOMAIN
            .into_iter()
            .collect::<BTreeSet<_>>(),
    );
    assert_eq!(
        full_domain
            .iter()
            .map(|case| case.initial.last_used_ability)
            .collect::<BTreeSet<_>>(),
        BATTLE_SCRIPT_TRYCOPYABILITY_LAST_USED_ABILITY_BOUNDARY_DOMAIN
            .into_iter()
            .collect::<BTreeSet<_>>(),
    );

    for case in full_domain {
        let target_ability = case.initial.abilities[usize::from(target)];
        if BATTLE_SCRIPT_TRYCOPYABILITY_FAILURE_ABILITY_DOMAIN.contains(&target_ability) {
            assert_eq!(
                case.controls,
                &[BattleScriptTrycopyabilityControl::FailJump]
            );
            assert_eq!(case.expected, Some(case.initial));
        } else {
            let expected = case.expected.expect("successful full-domain output");
            assert_eq!(case.controls, &[BattleScriptTrycopyabilityControl::Advance]);
            assert_eq!(expected.abilities[usize::from(attacker)], target_ability);
            assert_eq!(expected.last_used_ability, target_ability);
        }
    }
}

#[test]
fn compact_pair_matrix_covers_all_sixteen_pairs_both_failures_success_boundaries_and_aliases() {
    let matrix = BATTLE_SCRIPT_TRYCOPYABILITY_CASES
        .iter()
        .filter(|case| case.category == "attacker-target-pair-failure-success-boundary-matrix")
        .collect::<Vec<_>>();
    assert_eq!(matrix.len(), 96);

    let observed = matrix
        .iter()
        .map(|case| {
            let attacker = case.initial.attacker.expect("matrix attacker");
            let target = case.initial.target.expect("matrix target");
            (
                attacker.as_u8(),
                target.as_u8(),
                case.initial.abilities[target.index()],
            )
        })
        .collect::<BTreeSet<_>>();
    let mut expected = BTreeSet::new();
    for attacker in BATTLE_SCRIPT_TRYCOPYABILITY_ATTACKER_DOMAIN {
        for target in BATTLE_SCRIPT_TRYCOPYABILITY_TARGET_DOMAIN {
            for ability in BATTLE_SCRIPT_TRYCOPYABILITY_FAILURE_ABILITY_DOMAIN
                .into_iter()
                .chain(BATTLE_SCRIPT_TRYCOPYABILITY_SUCCESS_ABILITY_BOUNDARY_DOMAIN)
            {
                expected.insert((attacker, target, ability));
            }
        }
    }
    assert_eq!(observed, expected);
    assert_eq!(
        matrix
            .iter()
            .filter(|case| case.initial.attacker == case.initial.target)
            .count(),
        24,
        "four aliases must retain each of the six branch abilities",
    );

    for case in matrix {
        let target = case.initial.target.expect("matrix target");
        let ability = case.initial.abilities[target.index()];
        let expected_control =
            if BATTLE_SCRIPT_TRYCOPYABILITY_FAILURE_ABILITY_DOMAIN.contains(&ability) {
                BattleScriptTrycopyabilityControl::FailJump
            } else {
                BattleScriptTrycopyabilityControl::Advance
            };
        assert_eq!(
            case.controls,
            &[expected_control],
            "matrix branch for {}",
            case.label
        );
    }
}

#[test]
fn ordered_missing_roles_sibling_preservation_explicit_alias_and_repetition_are_pinned() {
    let missing_both = BATTLE_SCRIPT_TRYCOPYABILITY_CASES
        .iter()
        .find(|case| case.label == "missing_attacker_and_target_roles_attacker_error_first")
        .expect("missing-both vector");
    assert_eq!(missing_both.initial.attacker, None);
    assert_eq!(missing_both.initial.target, None);
    assert!(missing_both.controls.is_empty());
    assert_eq!(
        missing_both.expected_error,
        Some("Battle Script hit-chain command requires a attacker role"),
    );

    let missing_attacker = BATTLE_SCRIPT_TRYCOPYABILITY_CASES
        .iter()
        .find(|case| case.label == "missing_attacker_role_precedes_target_ability_read")
        .expect("missing-attacker vector");
    assert_eq!(missing_attacker.initial.attacker, None);
    assert_eq!(
        missing_attacker.initial.target.map(|value| value.as_u8()),
        Some(3)
    );
    assert_eq!(
        missing_attacker.expected_error,
        Some("Battle Script hit-chain command requires a attacker role"),
    );

    let missing_target = BATTLE_SCRIPT_TRYCOPYABILITY_CASES
        .iter()
        .find(|case| case.label == "missing_target_role_after_attacker_resolution")
        .expect("missing-target vector");
    assert_eq!(
        missing_target.initial.attacker.map(|value| value.as_u8()),
        Some(2)
    );
    assert_eq!(missing_target.initial.target, None);
    assert_eq!(
        missing_target.expected_error,
        Some("Battle Script hit-chain command requires a target role"),
    );

    let siblings = BATTLE_SCRIPT_TRYCOPYABILITY_CASES
        .iter()
        .find(|case| {
            case.label
                == "success_copy_mutates_only_attacker_and_last_used_ability_preserves_siblings"
        })
        .expect("sibling-preservation vector");
    let siblings_expected = siblings.expected.expect("sibling-preservation output");
    assert_eq!(siblings.initial.abilities, [7, 128, 1, 26]);
    assert_eq!(siblings.initial.last_used_ability, 255);
    assert_eq!(siblings_expected.abilities, [7, 128, 26, 26]);
    assert_eq!(siblings_expected.last_used_ability, 26);
    assert_eq!(siblings_expected.attacker, siblings.initial.attacker);
    assert_eq!(siblings_expected.target, siblings.initial.target);

    let alias = BATTLE_SCRIPT_TRYCOPYABILITY_CASES
        .iter()
        .find(|case| {
            case.label
                == "explicit_alias_success_preserves_all_abilities_and_overwrites_last_used_ability"
        })
        .expect("explicit alias vector");
    assert_eq!(alias.initial.attacker.map(|value| value.as_u8()), Some(3));
    assert_eq!(alias.initial.target.map(|value| value.as_u8()), Some(3));
    assert_eq!(
        alias.controls,
        &[BattleScriptTrycopyabilityControl::Advance]
    );
    assert_eq!(
        alias.expected.expect("alias output").abilities,
        alias.initial.abilities
    );
    assert_eq!(alias.expected.expect("alias output").last_used_ability, 26);

    let repeated_success = BATTLE_SCRIPT_TRYCOPYABILITY_CASES
        .iter()
        .find(|case| case.label == "repeated_success_copy_advances_twice_and_is_value_idempotent")
        .expect("repeated-success vector");
    assert_eq!(repeated_success.applications, 2);
    assert_eq!(
        repeated_success.controls,
        &[
            BattleScriptTrycopyabilityControl::Advance,
            BattleScriptTrycopyabilityControl::Advance,
        ],
    );
    assert_eq!(
        repeated_success
            .expected
            .expect("repeated-success output")
            .last_used_ability,
        26,
    );

    let repeated_failure = BATTLE_SCRIPT_TRYCOPYABILITY_CASES
        .iter()
        .find(|case| {
            case.label == "repeated_failure_ability_fail_jumps_twice_and_preserves_complete_state"
        })
        .expect("repeated-failure vector");
    assert_eq!(repeated_failure.applications, 2);
    assert_eq!(
        repeated_failure.controls,
        &[
            BattleScriptTrycopyabilityControl::FailJump,
            BattleScriptTrycopyabilityControl::FailJump,
        ],
    );
    assert_eq!(repeated_failure.expected, Some(repeated_failure.initial));
}

#[test]
fn fixed_four_slot_u8_domains_and_source_constants_are_retained() {
    assert_eq!(BATTLE_SCRIPT_TRYCOPYABILITY_BATTLER_COUNT, 4);
    assert_eq!(
        BATTLE_SCRIPT_TRYCOPYABILITY_BATTLERS.map(|battler| battler.as_u8()),
        BATTLE_SCRIPT_TRYCOPYABILITY_ATTACKER_DOMAIN,
    );
    assert_eq!(
        BATTLE_SCRIPT_TRYCOPYABILITY_ATTACKER_DOMAIN,
        BATTLE_SCRIPT_TRYCOPYABILITY_TARGET_DOMAIN,
    );
    assert_eq!(BATTLE_SCRIPT_TRYCOPYABILITY_ATTACKER_DOMAIN, [0, 1, 2, 3]);
    assert_eq!(
        BATTLE_SCRIPT_TRYCOPYABILITY_TARGET_ABILITY_DOMAIN,
        core::array::from_fn(|value| value as u8),
    );
    assert_eq!(
        BATTLE_SCRIPT_TRYCOPYABILITY_FAILURE_ABILITY_DOMAIN,
        [
            BATTLE_SCRIPT_TRYCOPYABILITY_ABILITY_NONE,
            BATTLE_SCRIPT_TRYCOPYABILITY_ABILITY_WONDER_GUARD
        ],
    );
    assert_eq!(BATTLE_SCRIPT_TRYCOPYABILITY_ABILITY_NONE, 0);
    assert_eq!(BATTLE_SCRIPT_TRYCOPYABILITY_ABILITY_WONDER_GUARD, 25);
    assert_eq!(
        BATTLE_SCRIPT_TRYCOPYABILITY_SUCCESS_ABILITY_BOUNDARY_DOMAIN,
        [1, 24, 26, 255],
    );
    assert_eq!(
        BATTLE_SCRIPT_TRYCOPYABILITY_LAST_USED_ABILITY_BOUNDARY_DOMAIN,
        [0, 1, 24, 25, 26, 255],
    );
    assert_eq!(BATTLE_SCRIPT_TRYCOPYABILITY_FULL_DOMAIN_ROLE_PAIR, (0, 1));
}

#[test]
fn domain_category_branch_censuses_and_corpus_hash_are_ratchet_pinned() {
    assert_eq!(
        BATTLE_SCRIPT_TRYCOPYABILITY_DOMAIN_CENSUS,
        [
            ("battler-slots", 4),
            ("active-ability-u8-values", 256),
            ("last-used-ability-u8-values", 256),
            ("target-ability-full-domain-probes", 256),
            ("prior-last-used-ability-boundary-values", 6),
            ("attacker-role-values", 4),
            ("target-role-values", 4),
            ("complete-attacker-target-role-pairs", 16),
            ("failure-ability-values", 2),
            ("success-ability-boundary-values", 4),
            ("attacker-target-pair-branch-matrix-cases", 96),
            ("typed-ordered-missing-role-cases", 3),
            ("application-count-values", 2),
            ("party-ability-slot-fields-in-projection", 0),
            ("failure-pointer-fields-in-projection", 0),
            ("absolute-program-counter-fields-in-projection", 0),
            ("abi-exports-added", 0),
            ("unsupported-barriers-added", 0),
            ("generated-file-byte-limit-exclusive", 5_000_000),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_TRYCOPYABILITY_CATEGORY_CENSUS,
        [
            ("attacker-target-pair-failure-success-boundary-matrix", 96),
            ("explicit-alias-preservation", 1),
            ("non-alias-target-ability-u8-full-domain", 256),
            ("ordered-missing-role-errors", 3),
            ("repeated-failure-preservation", 1),
            ("repeated-success-copy", 1),
            ("sibling-preservation", 1),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_TRYCOPYABILITY_BRANCH_CENSUS,
        [
            ("advance", 320),
            ("advance-then-advance", 1),
            ("fail-jump", 34),
            ("fail-jump-then-fail-jump", 1),
            ("missing-attacker-role", 2),
            ("missing-target-role", 1),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_TRYCOPYABILITY_VECTOR_CORPUS_SHA256,
        "afbfd05ca218aa26d69aca4c8f6f771368c6a59b1b1be4bade6ccf65fc4cb536",
    );
}
